import re
from datetime import time
def task_func(logs: list):
    error_times = []
    total_seconds = 0
    pattern = re.compile(r'(\d{4}-\d{2}-\d{2})\s+(\d{2}):(\d{2}):(\d{2})\s+ERROR')
    for log in logs:
        m = pattern.search(log)
        if m:
            h, mi, s = int(m.group(2)), int(m.group(3)), int(m.group(4))
            error_times.append(time(h, mi, s))
            total_seconds += h * 3600 + mi * 60 + s
    if not error_times:
        return [], time(0, 0, 0)
    avg = total_seconds // len(error_times)
    avg_h = avg // 3600
    avg_m = (avg % 3600) // 60
    avg_s = avg % 60
    return error_times, time(avg_h, avg_m, avg_s)
